import { describe, expect, it } from 'vitest'
import vectors from '../../../scripts/pnl_vectors.json'
import { dec } from './money'
import { pnl, pnlPercent, validateStopLoss, validateTakeProfit } from './pnl'
import type { Direction } from '@/types'

interface Vector {
  direction: Direction
  entry: string
  current: string
  stake: string
  want: string
}

/**
 * The vectors are generated by the Go implementation:
 *   go test ./internal/models -run TestDumpPnLVectors
 *
 * Running them through the client formula here is what stops the live number a
 * user watches drifting from the realised number they are paid. If this fails,
 * one of the two implementations changed without the other.
 */
describe('PnL parity with the server', () => {
  it.each(vectors as Vector[])(
    '$direction entry $entry current $current stake $stake',
    ({ direction, entry, current, stake, want }) => {
      expect(pnl(direction, entry, current, stake).toFixed(2)).toBe(dec(want).toFixed(2))
    },
  )

  it('never loses more than the stake once the close is floored at zero', () => {
    const loss = pnl('buy', '100', '0', '50')
    expect(loss.toFixed(2)).toBe('-50.00')
    const credit = dec('50').plus(loss)
    expect(Math.max(0, credit.toNumber())).toBe(0)
  })

  it('returns zero rather than dividing by a zero entry price', () => {
    expect(pnl('buy', '0', '100', '10').toNumber()).toBe(0)
  })
})

describe('pnlPercent', () => {
  it('expresses profit as a share of the stake', () => {
    expect(pnlPercent('buy', '100', '110', '50').toFixed(2)).toBe('10.00')
  })

  it('handles a zero stake without dividing by zero', () => {
    expect(pnlPercent('buy', '100', '110', '0').toNumber()).toBe(0)
  })
})

describe('level validation', () => {
  const entry = dec('100')

  it('refuses a stop loss above entry on a buy', () => {
    expect(validateStopLoss('buy', entry, dec('105'))).toMatch(/below/)
    expect(validateStopLoss('buy', entry, dec('95'))).toBeNull()
  })

  it('refuses a stop loss below entry on a sell', () => {
    expect(validateStopLoss('sell', entry, dec('95'))).toMatch(/above/)
    expect(validateStopLoss('sell', entry, dec('105'))).toBeNull()
  })

  it('refuses a take profit below entry on a buy', () => {
    expect(validateTakeProfit('buy', entry, dec('95'))).toMatch(/above/)
    expect(validateTakeProfit('buy', entry, dec('105'))).toBeNull()
  })

  it('refuses a take profit above entry on a sell', () => {
    expect(validateTakeProfit('sell', entry, dec('105'))).toMatch(/below/)
    expect(validateTakeProfit('sell', entry, dec('95'))).toBeNull()
  })

  it('treats a level exactly at entry as invalid in both directions', () => {
    expect(validateStopLoss('buy', entry, entry)).not.toBeNull()
    expect(validateTakeProfit('buy', entry, entry)).not.toBeNull()
  })
})
